from typing import List

def max_servings(Q: List[int], A: List[int], B: List[int]) -> int:
    N = len(Q)

    def canmake(K: int) -> bool:
        for i in range(K + 1):
            local_judge = True
            for j in range(N):
                if A[j] * i + B[j] * (K - i) > Q[j]:
                    local_judge = False
                    break
            if local_judge:
                return True
        return False

    L, R = 0, sum(Q) // min(min(a for a in A if a > 0), min(b for b in B if b > 0)) + 1
    while R - L > 1:
        C = (R + L) // 2
        if canmake(C):
            L = C
        else:
            R = C

    return L
